using System;using System.IO;class FormatTest{[STAThread]static int Main(string[] args){MeshFormats.Root=Path.GetFullPath(".");int failures=0;foreach(string file in args){try{using(var bmp=MeshFormats.Render(file)){bmp.Save(Path.Combine("fixtures",Path.GetFileName(file)+".png"));Console.WriteLine("PASS "+Path.GetFileName(file));}}catch(Exception e){Console.WriteLine("FAIL "+Path.GetFileName(file)+" "+e.Message);failures++;}}return failures;}}